import {dateLabel,money,DEPARTURE} from './model.mjs';
import {timelineFor} from './planning.mjs';
import {tradeoffModel,plotLabels,PLOT_NAMES} from './analysis-model.mjs';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const segmentColor=kind=>({origin:'#9aaeb1',destination:'#6f8f9a',ocean:'#3f7181',rail:'#7182a0',multimodal:'#8b7897',air:'#a0788a',delay:'#a66b7c'})[kind]||'#3f7181';
export function tradeoffView(settings,range,icon){
 const model=tradeoffModel(settings,range),{routes,shown,cap,days,deadline,points,hidden,selectedOutside}=model,labels=plotLabels(points,settings.selected);
 const x=day=>76+day/days*604,y=cost=>258-cost/cap*210;
 const currencyTick=cost=>cost===0?'€0':`€${cost/1000}k`,tickStep=cap>60000?20000:10000;
 return `<div class="tradeoffs-view analysis-view"><header class="analysis-heading"><div><h3>Cost and time, together.</h3><p>Left is faster. Lower is cheaper.</p></div><div class="analysis-range" aria-label="Chart range"><button data-action="chart-range" data-value="focus" data-focus="range-focus" aria-pressed="${range==='focus'}">Planning range</button><button data-action="chart-range" data-value="all" data-focus="range-all" aria-pressed="${range==='all'}">All 6 routes</button></div></header><div class="plot-caption">${icon('euro',15)} Total logistics cost <span>EUR · Handling, insurance & contingency included</span></div><svg class="analysis-plot" viewBox="0 0 720 322" role="group" aria-label="Total logistics cost against calendar-day transit time; ${shown.length} routes shown"><rect x="76" y="48" width="604" height="210" class="plot-surface"/><g class="analysis-grid">${Array.from({length:cap/tickStep+1},(_,i)=>{const cost=tickStep*i;return `<path d="M76 ${y(cost)}H680"/><text x="64" y="${y(cost)+4}" text-anchor="end">${currencyTick(cost)}</text>`}).join('')}${Array.from({length:days/10+1},(_,i)=>i*10).map(day=>`<path d="M${x(day)} 48V258"/><text x="${x(day)}" y="281" text-anchor="middle">${day}</text>`).join('')}</g>${settings.budget<=cap?`<path d="M76 ${y(settings.budget)}H680" class="analysis-budget"/><text x="83" y="${y(settings.budget)-8}" class="analysis-limit-label">Budget ${money(settings.budget)}</text>`:''}${deadline<=days?`<path d="M${x(deadline)} 42V258" class="analysis-deadline"/><text x="${Math.max(115,Math.min(625,x(deadline)))}" y="26" text-anchor="middle" class="analysis-limit-label">Deadline · ${dateLabel(settings.deadline)}</text>`:''}${points.toSorted((a,b)=>b.radius-a.radius).map(point=>`<g class="chart-point ${point.id===settings.selected?'is-selected':''}" role="button" tabindex="0" data-action="select" data-value="${point.id}" data-focus="plot-${point.id}" aria-describedby="route-tooltip" aria-label="Select ${esc(point.name)} on chart"><circle class="chart-hit-area" cx="${point.x}" cy="${point.y}" r="${Math.max(12,point.radius)}" fill="transparent"/>${point.id===settings.baseline?`<circle cx="${point.x}" cy="${point.y}" r="${point.radius+4}" class="analysis-reference"/>`:''}${point.id===settings.selected?`<circle cx="${point.x}" cy="${point.y}" r="${point.radius+7}" class="analysis-selection"/>`:''}<circle class="analysis-point ${point.feasible?'viable':'outside'}" cx="${point.x}" cy="${point.y}" r="${point.radius}"/></g>`).join('')}<g class="plot-labels" aria-hidden="true">${labels.map(label=>`<path d="M${label.pointX} ${label.pointY}L${Math.max(label.x,Math.min(label.x+label.w,label.pointX))} ${Math.max(label.y,Math.min(label.y+label.h,label.pointY))}"/><rect x="${label.x}" y="${label.y}" width="${label.w}" height="${label.h}" rx="4"/><text x="${label.x+7}" y="${label.y+16}">${label.label}</text>`).join('')}</g><text class="analysis-axis-label" x="680" y="312" text-anchor="end">Calendar days</text></svg><div class="analysis-notes"><span class="analysis-legend"><i class="legend-viable"></i>Within limits <i class="legend-outside"></i>Outside a limit</span><span>${shown.length}/6 shown · Area: CO₂e</span>${hidden?`<button class="text-button" data-action="chart-range" data-value="all">${hidden} higher-cost routes ${icon('arrow',13)}</button>`:''}</div>${selectedOutside?'<p class="plot-outside-note">The selected route is above this range. Choose All 6 routes to see it on the plot.</p>':''}<div class="analysis-route-key" aria-label="Select a route">${routes.map(route=>`<button data-action="select" data-value="${route.id}" data-focus="analysis-route-${route.id}" aria-label="Inspect ${esc(route.name)}" aria-pressed="${settings.selected===route.id}"><span class="analysis-key-name">${icon(route.feasible?'check':'alert',14)}${PLOT_NAMES[route.id]}<small>${route.id===settings.baseline?'Baseline':route.mode==='ocean'?'Ocean':route.mode==='multimodal'?'Sea–air':route.mode==='rail'?'Rail':'Air'}</small></span><strong>${money(route.cost)} <span>· ${route.days}d</span></strong></button>`).join('')}</div></div>`;
}
export function journeyView(route,settings,activeIndex,icon){
 const timeline=timelineFor(route.id,settings),active=timeline.segments[Math.min(activeIndex,timeline.segments.length-1)]||timeline.segments[0];
 const deadline=Math.round((Date.parse(settings.deadline+'T12:00:00Z')-Date.parse(DEPARTURE+'T12:00:00Z'))/86400000),cap=Math.max(timeline.totalDays,deadline)+3;
 return `<div class="journey-view analysis-view"><header class="analysis-heading journey-release-heading"><div><span class="analysis-eyebrow">PLANNED JOURNEY</span><h3>${esc(route.short)}</h3><p>${timeline.totalDays} calendar days · Departing ${dateLabel(DEPARTURE)}</p></div><div class="journey-arrival"><span>Estimated arrival</span><strong>${dateLabel(timeline.arrival)}</strong><small class="${route.buffer>=0?'good':'caution'}">${route.buffer>=0?`${route.buffer}d before deadline`:`${-route.buffer}d after deadline`}</small></div></header><div class="journey-calendar"><div class="journey-calendar-labels"><span>${dateLabel(DEPARTURE)}</span><span style="left:${deadline/cap*100}%">Deadline ${dateLabel(settings.deadline)}</span></div><div class="journey-calendar-track" role="img" aria-label="${timeline.totalDays} planned days; arrival ${dateLabel(timeline.arrival)}, deadline ${dateLabel(settings.deadline)}"><div class="journey-calendar-stages" style="width:${timeline.totalDays/cap*100}%">${timeline.segments.map(segment=>`<span class="${segment.id===active.id?'is-active':''}" style="width:${segment.days/timeline.totalDays*100}%;background:${segmentColor(segment.kind)}"></span>`).join('')}</div><i style="left:${deadline/cap*100}%" title="Delivery deadline"></i></div></div><div class="journey-stage-heading"><strong>Planned stages</strong><span>Select a stage to highlight it</span></div><div class="journey-stage-grid">${timeline.segments.map(segment=>`<button class="journey-stage-card ${segment.id===active.id?'is-active':''} ${segment.kind==='delay'?'is-delay':''}" data-action="journey-leg" data-value="${segment.id}" data-focus="leg-${segment.id}" aria-pressed="${segment.id===active.id}"><span class="stage-index">${String(segment.id+1).padStart(2,'0')}</span><span class="stage-copy"><strong>${esc(segment.place)}</strong><small>${esc(segment.task)}</small><span>${dateLabel(segment.startDate)} → ${dateLabel(segment.endDate)}</span></span><span class="stage-days">${segment.days}<small>${segment.days===1?'day':'days'}</small></span></button>`).join('')}</div><footer class="journey-release-footer"><span>${active.kind==='delay'?'Stress-test hold · Adds time, not transport emissions.':'Illustrative planning sequence · No carrier confirmation.'}</span><button class="text-button" data-action="itinerary">Full itinerary ${icon('arrow',14)}</button></footer></div>`;
}
